/**
 * LinkedIn Gmail parser: title, company, apply_url (cleaned)
 */

function unique(arr) {
  return [...new Set(arr.filter(Boolean))];
}

function stripHtml(html) {
  return (html || "")
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, "")
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, "")
    .replace(/<[^>]+>/g, "\n")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&middot;/gi, " · ")
    .replace(/\n{2,}/g, "\n")
    .trim();
}

function cleanText(s) {
  return (s || "")
    .replace(/&middot;/gi, " · ")
    .replace(/\s+/g, " ")
    .trim();
}

function extractApplyLinks(raw) {
  const links = [];
  const re = /https:\/\/www\.linkedin\.com\/comm\/jobs\/view\/[^\s)"']+/gi;
  let m;
  while ((m = re.exec(raw || "")) !== null) {
    links.push(m[0].replace(/[.,;]+$/, ""));
  }
  return unique(links);
}

function isNoiseLine(s) {
  const t = cleanText(s).toLowerCase();
  return (
    !t ||
    t === "manage alerts" ||
    t.startsWith("your job alert") ||
    t.startsWith("manage your job alerts") ||
    t.startsWith("view all jobs") ||
    t.startsWith("apply with") ||
    t.includes("linkedin.com/comm/jobs/alerts")
  );
}

function cleanCompany(line) {
  let c = cleanText(line);
  // remove location/on-site tails after separator
  c = c.split(" · ")[0].trim();
  c = c.replace(/\(on-site\)|\(hybrid\)|\(remote\)/gi, "").trim();
  return c;
}

function looksLikeTitle(line) {
  const t = cleanText(line);
  if (!t || t.length > 140) return false;
  return /engineer|developer|manager|analyst|specialist|scientist|architect|lead|principal|technician/i.test(t);
}

function looksLikeCompany(line) {
  const c = cleanCompany(line);
  if (!c || c.length > 100) return false;
  if (isNoiseLine(c)) return false;
  if (/^view job/i.test(c)) return false;
  return true;
}

const out = [];

for (const item of $input.all()) {
  const subject = cleanText(item.json.subject || "LinkedIn alert");
  const html = item.json.html || item.json.textHtml || "";
  const textRaw = item.json.text || "";
  const textAsHtml = item.json.textAsHtml || "";
  const text = stripHtml(html) || textRaw || stripHtml(textAsHtml);

  const links = unique([
    ...extractApplyLinks(textRaw),
    ...extractApplyLinks(stripHtml(textAsHtml)),
    ...extractApplyLinks(html),
  ]);

  const lines = text.split("\n").map(cleanText).filter(Boolean);
  const jobs = [];

  // Try to find "Title" + nearby "Company" patterns
  for (let i = 0; i < lines.length; i++) {
    if (!looksLikeTitle(lines[i])) continue;

    const title = lines[i];
    let company = "";

    // Prefer immediate next line as company, then previous line
    if (looksLikeCompany(lines[i + 1])) company = cleanCompany(lines[i + 1]);
    else if (looksLikeCompany(lines[i - 1])) company = cleanCompany(lines[i - 1]);

    if (!company) continue;

    jobs.push({ title, company });
  }

  // Pair jobs with links by index
  for (let i = 0; i < jobs.length; i++) {
    out.push({
      json: {
        title: jobs[i].title,
        company: jobs[i].company,
        discovery_url: links[i] || links[0] || "",
        status: "needs_jd",
        source: "linkedin_email",
      },
    });
  }

  // Fallback row if no parsed jobs
  if (jobs.length === 0) {
    out.push({
      json: {
        title: subject || "LinkedIn alert",
        company: "Unknown",
        discovery_url: links[0] || "",
        status: "needs_jd",
        source: "linkedin_email",
      },
    });
  }
}

return out;

/**
 * Dice Gmail parser: title, company, discovery_url, status, source
 */

function clean(s) {
  return (s || "")
    .replace(/[<>]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function isDiceJobUrl(line) {
  return /^https:\/\/www\.dice\.com\/job-detail\//i.test(clean(line));
}

function isNoiseLine(line) {
  const t = clean(line).toLowerCase();

  return (
    !t ||
    t.includes("where tech connects") ||
    t === "log in" ||
    t.startsWith("hi,") ||
    t.startsWith("new matches for") ||
    t.startsWith("manage your") ||
    t.startsWith("view all jobs") ||
    t.includes("linkedin") ||
    t.includes("twitter") ||
    t.includes("facebook") ||
    t.includes("youtube") ||
    t.includes("subscribed for job alerts") ||
    t.includes("dice knowledge center") ||
    t.includes("unsubscribe") ||
    t.includes("copyright") ||
    t.includes("terms & conditions")
  );
}

const out = [];

for (const item of $input.all()) {
  const text =
    item.json.text ||
    item.json.textPlain ||
    item.json.body ||
    item.json.snippet ||
    "";

  const lines = text
    .split("\n")
    .map(clean)
    .filter(line => line && !isNoiseLine(line));

  for (let i = 0; i < lines.length; i++) {
    if (!isDiceJobUrl(lines[i])) continue;

    const title = lines[i - 1] || "";
    const discovery_url = lines[i];
    const company = lines[i + 1] || "";

    if (!title || !company || isDiceJobUrl(title) || isDiceJobUrl(company)) {
      continue;
    }

    out.push({
      json: {
        title,
        company,
        discovery_url,
        status: "needs_jd",
        source: "dice_email",
      },
    });
  }
}

return out;

/**
 * Indeed Gmail parser: one job per email
 * Output: title, company, discovery_url, status, source
 */

function clean(s) {
  return (s || "")
    .replace(/[\u034f\u200b\u200c\u200d\u2060\ufeff]/g, "")
    .replace(/[<>]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function getSender(item) {
  return clean(
    item.json.from?.text ||
    item.json.from?.value?.[0]?.address ||
    item.json.headers?.from ||
    item.json.replyTo?.text ||
    ""
  ).toLowerCase();
}

function isIndeedEmail(item) {
  const sender = getSender(item);
  return sender.includes("donotreply@match.indeed.com") ||
    sender.includes("match.indeed.com");
}

function extractIndeedUrl(text) {
  const links = (text || "").match(/https?:\/\/[^\s)"']+/gi) || [];
  return links.find(link =>
    /^https:\/\/cts\.indeed\.com\/v3\//i.test(link) ||
    /^https:\/\/[^/\s]*indeed\.com\//i.test(link)
  ) || "";
}

const out = [];

for (const item of $input.all()) {
  if (!isIndeedEmail(item)) continue;

  const subject = clean(item.json.subject || "");
  const text = item.json.text || item.json.textPlain || item.json.body || "";
  const discovery_url = extractIndeedUrl(text);

  let title = "";
  let company = "";

  // Best source for Indeed match emails:
  // "Operating System Virtualization Engineer @ Oxide Computer Company"
  if (subject.includes(" @ ")) {
    const parts = subject.split(" @ ");
    title = clean(parts[0]);
    company = clean(parts.slice(1).join(" @ "));
  }

  // Fallback only if subject format is missing
  if (!title || !company) {
    const lines = text
      .split("\n")
      .map(clean)
      .filter(Boolean);

    for (let i = 0; i < lines.length - 1; i++) {
      const current = lines[i];
      const next = lines[i + 1];

      if (
        current.startsWith("Hi ") ||
        current.startsWith("Your ") ||
        current.startsWith("It looks like") ||
        current.startsWith("Salary") ||
        current.startsWith("Job type") ||
        current.startsWith("Benefits") ||
        current.startsWith("- ") ||
        current.startsWith("View job")
      ) {
        continue;
      }

      title = current;
      company = next;
      break;
    }
  }

  if (title && company) {
    out.push({
      json: {
        title,
        company,
        discovery_url,
        status: "needs_jd",
        source: "indeed_email",
      },
    });
  }
}

return out;

/**
 * Glassdoor Gmail parser: only Job Alert emails
 * Output: title, company, discovery_url, status, source
 */

function clean(s) {
  return (s || "")
    .replace(/[\u034f\u200b\u200c\u200d\u2060\ufeff]/g, "")
    .replace(/[<>]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function getSender(item) {
  return clean(
    item.json.from?.text ||
    item.json.from?.value?.[0]?.address ||
    item.json.headers?.from ||
    item.json.replyTo?.text ||
    ""
  ).toLowerCase();
}

function isGlassdoorJobAlert(item) {
  const sender = getSender(item);
  const subject = clean(item.json.subject || "").toLowerCase();
  const text = item.json.text || item.json.textPlain || item.json.body || "";

  return (
    sender.includes("noreply@glassdoor.com") &&
    (
      subject.includes("job alert") ||
      text.toLowerCase().includes("your job listings for")
    )
  );
}

function cleanCompany(s) {
  return clean(s)
    .replace(/\s+\d+(\.\d+)?\s*★?$/g, "")
    .trim();
}

function isUrl(line) {
  return /^https?:\/\//i.test(clean(line)) || /^\[https?:\/\//i.test(clean(line));
}

function extractGlassdoorJobLinks(raw) {
  const text = (raw || "").replace(/&amp;/g, "&");
  const matches = text.match(/https?:\/\/[^\s"'<>]+/gi) || [];

  return [...new Set(matches)]
    .filter(link => /glassdoor\.com/i.test(link))
    .filter(link => !/\.(png|jpg|jpeg|gif|webp)(\?|$)/i.test(link))
    .filter(link => !/unsubscribe|privacy|settings|assets|media|brandRefresh|brand-views|pixel|logo/i.test(link))
    .filter(link => /\/job-listing\/|\/partner\/jobListing/i.test(link))
    .map(link => link.replace(/[),.;]+$/, ""));
}

function looksLikeLocation(line) {
  const t = clean(line);
  return /^[A-Za-z .'-]+,\s*[A-Z]{2}$/.test(t) || /^United States( of America)?$/i.test(t);
}

function looksLikeSalary(line) {
  return /\$\d+K?\s*-\s*\$\d+K?/i.test(clean(line));
}

function looksLikeAge(line) {
  return /^(just posted|\d+[hd]|today|yesterday)$/i.test(clean(line));
}

function isNoise(line) {
  const t = clean(line).toLowerCase();

  return (
    !t ||
    t === "glassdoor" ||
    t === "avatar" ||
    t === "easy apply" ||
    t.startsWith("job alert:") ||
    t.startsWith("check out your newest") ||
    t.startsWith("your job listings") ||
    t.startsWith("want more listings") ||
    t.startsWith("similar jobs") ||
    t.startsWith("create job alerts") ||
    t.startsWith("looking for something") ||
    t.startsWith("you can edit") ||
    t.startsWith("this message was sent") ||
    t.startsWith("privacy policy") ||
    t.startsWith("manage settings") ||
    t.startsWith("unsubscribe") ||
    t.startsWith("copyright") ||
    isUrl(t)
  );
}

const out = [];

for (const item of $input.all()) {
  if (!isGlassdoorJobAlert(item)) continue;

  const html = item.json.html || item.json.textHtml || "";
  const text = item.json.text || item.json.textPlain || item.json.body || "";

  const links = extractGlassdoorJobLinks(html + "\n" + text);

  const rawLines = text
    .split("\n")
    .map(clean)
    .filter(Boolean);

  const start = rawLines.findIndex(line =>
    clean(line).toLowerCase().startsWith("your job listings for")
  );

  const end = rawLines.findIndex(line =>
    clean(line).toLowerCase() === "see more jobs"
  );

  const scoped = rawLines.slice(
    start >= 0 ? start + 1 : 0,
    end > 0 ? end : rawLines.length
  );

  const lines = scoped
    .filter(line => !isNoise(line));

  let jobIndex = 0;

  for (let i = 0; i < lines.length - 2; i++) {
    const company = cleanCompany(lines[i]);
    const title = clean(lines[i + 1]);
    const location = clean(lines[i + 2]);

    if (!company || !title || !looksLikeLocation(location)) continue;
    if (looksLikeSalary(company) || looksLikeAge(company)) continue;

    out.push({
      json: {
        title,
        company,
        discovery_url: links[jobIndex] || "",
        status: "needs_jd",
        source: "glassdoor_email",
      },
    });

    jobIndex++;
    i += 2;
  }
}

return out;

/**
 * Handshake Gmail parser
 * Output: title, company, discovery_url, status, source
 */

function clean(s) {
  return (s || "")
    .replace(/[\u034f\u200b\u200c\u200d\u2060\ufeff]/g, "")
    .replace(/[<>]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function getSender(item) {
  return clean(
    item.json.from?.text ||
    item.json.from?.value?.[0]?.address ||
    item.json.headers?.from ||
    item.json.replyTo?.text ||
    ""
  ).toLowerCase();
}

function isHandshakeEmail(item) {
  return getSender(item).includes("handshake@notifications.joinhandshake.com");
}

function extractHandshakeUrl(raw) {
  const matches = (raw || "").replace(/&amp;/g, "&").match(/https?:\/\/[^\s"'<>]+/gi) || [];
  return matches.find(link =>
    /joinhandshake\.com/i.test(link) &&
    !/unsubscribe|preferences|instagram|tiktok|app-store|play-store/i.test(link)
  ) || "";
}

const out = [];

for (const item of $input.all()) {
  if (!isHandshakeEmail(item)) continue;

  const html = item.json.html || item.json.textHtml || "";
  const text = item.json.text || item.json.textPlain || item.json.body || "";

  const discovery_url = extractHandshakeUrl(html + "\n" + text);

  const lines = text
    .split("\n")
    .map(clean)
    .filter(Boolean);

  const viewJobIndex = lines.findIndex(line =>
    line.toLowerCase() === "view job"
  );

  // Handshake format:
  // company
  // title
  // Full-Time • Cape Canaveral, FL (Onsite)
  // View job
  let title = "";
  let company = "";

  if (viewJobIndex >= 2) {
    title = lines[viewJobIndex - 2];
    company = lines[viewJobIndex - 3] || "";
  }

  if (!title || !company) {
    const logoIndex = lines.findIndex(line =>
      line.toLowerCase().endsWith(" logo")
    );

    if (logoIndex >= 2) {
      company = lines[logoIndex + 1] || "";
      title = lines[logoIndex + 2] || "";
    }
  }

  if (title && company) {
    out.push({
      json: {
        title,
        company,
        discovery_url,
        status: "needs_jd",
        source: "handshake_email",
      },
    });
  }
}

return out;

const DEBUG = false;

const DAY_MS = 24 * 60 * 60 * 1000;
const cutoff = Date.now() - DAY_MS;

function clean(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function stripHtml(html) {
  let text = String(html || '');

  text = text
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|ul|ol|h1|h2|h3|h4|h5|h6|tr)>/gi, '\n')
    .replace(/<li[^>]*>/gi, '- ')
    .replace(/<[^>]+>/g, ' ');

  const entities = {
    '&nbsp;': ' ',
    '&amp;': '&',
    '&quot;': '"',
    '&#39;': "'",
    '&apos;': "'",
    '&lt;': '<',
    '&gt;': '>',
    '&mdash;': '-',
    '&ndash;': '-',
    '&rsquo;': "'",
    '&lsquo;': "'",
    '&rdquo;': '"',
    '&ldquo;': '"',
  };

  for (const [entity, replacement] of Object.entries(entities)) {
    text = text.replace(new RegExp(entity, 'gi'), replacement);
  }

  return text
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
    .replace(/&#x([a-f0-9]+);/gi, (_, code) => String.fromCharCode(parseInt(code, 16)))
    .replace(/\r/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n[ \t]+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function isEnabled(value) {
  return value === true || value === 1 || ['true', '1', 'yes', 'y'].includes(clean(value).toLowerCase());
}

function getConfigValue(rows, key) {
  const row = rows.find((item) => clean(item.json.key).toLowerCase() === key);
  return clean(row?.json.value || '');
}

function splitTerms(value) {
  return clean(value)
    .split(/[,;|\n]/)
    .map((term) => clean(term).toLowerCase())
    .filter(Boolean);
}

function tokenize(value) {
  return clean(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .split(/\s+/)
    .filter((word) => word.length >= 3);
}

function jaccardSimilarity(a, b) {
  const aTokens = new Set(tokenize(a));
  const bTokens = new Set(tokenize(b));

  if (!aTokens.size || !bTokens.size) return 0;

  let intersection = 0;
  for (const token of aTokens) {
    if (bTokens.has(token)) intersection += 1;
  }

  const union = new Set([...aTokens, ...bTokens]).size;
  return intersection / union;
}

function titleSimilarity(title, reference) {
  const titleText = clean(title).toLowerCase();
  const referenceText = clean(reference).toLowerCase();

  if (!titleText || !referenceText) return 0;
  if (titleText.includes(referenceText) || referenceText.includes(titleText)) return 1;

  return jaccardSimilarity(titleText, referenceText);
}

function getBestMatch(title, terms) {
  let bestTerm = '';
  let bestScore = 0;

  for (const term of terms) {
    const score = titleSimilarity(title, term);

    if (score > bestScore) {
      bestScore = score;
      bestTerm = term;
    }
  }

  return { term: bestTerm, score: bestScore };
}

function matchesRole(title, terms) {
  const best = getBestMatch(title, terms);
  return best.score >= 0.25;
}

function getBucket(title, buckets) {
  let bestBucket = '';
  let bestScore = 0;

  for (const bucket of buckets) {
    const best = getBestMatch(title, bucket.terms);

    if (best.score > bestScore) {
      bestScore = best.score;
      bestBucket = bucket.name;
    }
  }

  return bestScore >= 0.25 ? bestBucket : '';
}

function normalizeCountry(value) {
  const v = clean(value).toLowerCase();

  if (['usa', 'us', 'u.s.', 'united states', 'united states of america'].includes(v)) return 'usa';
  if (['uk', 'united kingdom', 'england', 'scotland', 'wales'].includes(v)) return 'uk';
  if (['canada', 'ca'].includes(v)) return 'canada';

  return v;
}

function getAllowedCountries(configRows) {
  return splitTerms(getConfigValue(configRows, 'allowed_countries'))
    .map(normalizeCountry)
    .filter(Boolean);
}

function locationMatchesAllowedCountries(location, allowedCountries) {
  if (!allowedCountries.length) return true;

  const raw = clean(location);
  const loc = raw.toLowerCase();

  if (!raw) return false;

  if (allowedCountries.includes('usa')) {
    const usStates = /\b(AL|AK|AZ|AR|CA|CO|CT|DE|FL|GA|HI|IA|ID|IL|IN|KS|KY|LA|MA|MD|ME|MI|MN|MO|MS|MT|NC|ND|NE|NH|NJ|NM|NV|NY|OH|OK|OR|PA|RI|SC|SD|TN|TX|UT|VA|VT|WA|WI|WV|WY|DC)\b/;

    if (
      loc.includes('united states') ||
      loc.includes('usa') ||
      loc.includes('u.s.') ||
      loc.includes('us-') ||
      usStates.test(raw)
    ) {
      return true;
    }
  }

  if (allowedCountries.includes('uk')) {
    if (
      loc.includes('united kingdom') ||
      loc.includes('uk') ||
      loc.includes('england') ||
      loc.includes('scotland') ||
      loc.includes('wales')
    ) {
      return true;
    }
  }

  if (allowedCountries.includes('canada')) {
    const canadaProvinces = /\b(ON|BC|QC|AB|MB|SK|NS|NB|NL|PE|YT|NT|NU)\b/;

    if (loc.includes('canada') || canadaProvinces.test(raw)) {
      return true;
    }
  }

  return false;
}

function deriveGreenhouseSlug(row) {
  if (clean(row.slug)) return clean(row.slug);

  const rawUrl = clean(row.career_page_url || row.endpoint);
  if (!rawUrl) return '';

  let match = rawUrl.match(/^https?:\/\/boards\.greenhouse\.io\/([^/?#]+)/i);
  if (match) return decodeURIComponent(match[1]);

  match = rawUrl.match(/^https?:\/\/boards-api\.greenhouse\.io\/v1\/boards\/([^/?#]+)/i);
  if (match) return decodeURIComponent(match[1]);

  return '';
}

function isGreenhouseRow(row) {
  const atsType = clean(row.ats_type).toLowerCase();
  const url = clean(row.career_page_url || row.endpoint).toLowerCase();

  return atsType === 'greenhouse' || url.includes('greenhouse.io');
}

function getJobUrl(job) {
  return clean(job.absolute_url || job.url || '');
}

function getCompaniesFromInput() {
  const inputRows = $input.all().map((item) => item.json);
  const greenhouseRows = inputRows.filter(isGreenhouseRow);

  if (greenhouseRows.length) return inputRows;

  try {
    return $('Read companies tab').all().map((item) => item.json);
  } catch (error) {
    return inputRows;
  }
}

const configRows = $('Read config tab').all();
const companies = getCompaniesFromInput();

const allowedCountries = getAllowedCountries(configRows);

const systemsTitleReferences = splitTerms(getConfigValue(configRows, 'systems_title_references'));
const mechanicalTitleReferences = splitTerms(getConfigValue(configRows, 'mechanical_title_references'));
const controlsTitleReferences = splitTerms(getConfigValue(configRows, 'controls_title_references'));

const systemsKeywords = splitTerms(getConfigValue(configRows, 'systems_keywords'));
const mechanicalKeywords = splitTerms(getConfigValue(configRows, 'mechanical_keywords'));
const controlsKeywords = splitTerms(getConfigValue(configRows, 'controls_keywords'));

const buckets = [
  {
    name: 'systems',
    terms: [...systemsTitleReferences, ...systemsKeywords],
  },
  {
    name: 'mechanical',
    terms: [...mechanicalTitleReferences, ...mechanicalKeywords],
  },
  {
    name: 'controls',
    terms: [...controlsTitleReferences, ...controlsKeywords],
  },
];

const uniqueTerms = [...new Set([
  ...systemsTitleReferences,
  ...mechanicalTitleReferences,
  ...controlsTitleReferences,
  ...systemsKeywords,
  ...mechanicalKeywords,
  ...controlsKeywords,
])];

const greenhouseCompanies = companies.filter((row) => isEnabled(row.enabled) && isGreenhouseRow(row));

const out = [];

if (DEBUG) {
  out.push({
    json: {
      title: 'DEBUG Greenhouse input',
      company: '',
      location: '',
      apply_url: '',
      discovery_url: '',
      posted_at: '',
      needs_manual_jd: true,
      full_jd: `input_rows=${companies.length}; enabled_greenhouse_rows=${greenhouseCompanies.length}; configured_terms=${uniqueTerms.length}; allowed_countries=${allowedCountries.join(', ')}`,
      status: 'debug',
      source: 'greenhouse',
      bucket_selected: '',
      score: '',
      rank_reason: '',
    },
  });
}

for (const companyRow of greenhouseCompanies) {
  const slug = deriveGreenhouseSlug(companyRow);
  if (!slug) continue;

  const company = clean(companyRow.company) || slug;
