  return atsType === 'lever' || url.includes('jobs.lever.co') || url.includes('api.lever.co');
}

function getLeverJobUrl(job) {
  return clean(job.hostedUrl || job.applyUrl || job.url || '');
}

function getLeverLocation(job) {
  if (job.categories?.location) return clean(job.categories.location);
  if (Array.isArray(job.workplaceType)) return clean(job.workplaceType.join(', '));
  return '';
}

function getLeverPostedAt(job) {
  if (job.createdAt) return new Date(job.createdAt).toISOString();
  if (job.updatedAt) return new Date(job.updatedAt).toISOString();
  return '';
}

function getLeverTimestamp(job) {
  return Number(job.createdAt || job.updatedAt || 0);
}

function getLeverDescription(job) {
  const parts = [];

  if (job.description) parts.push(job.description);
  if (job.descriptionPlain) parts.push(job.descriptionPlain);

  if (Array.isArray(job.lists)) {
    for (const list of job.lists) {
      if (list.text) parts.push(list.text);
      if (Array.isArray(list.content)) {
        for (const item of list.content) {
          parts.push(item.text || item);
        }
      }
    }
  }

  return stripHtml(parts.join('\n\n'));
}

