    .replace(/&rsquo;/gi, "'")
    .replace(/&lsquo;/gi, "'")
    .replace(/&rdquo;/gi, '"')
    .replace(/&ldquo;/gi, '"')
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
    .replace(/&#x([a-f0-9]+);/gi, (_, code) => String.fromCharCode(parseInt(code, 16)))
    .replace(/\r/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n[ \t]+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function isEnabled(value) {
  return value === true || value === 1 || ['true', '1', 'yes', 'y'].includes(clean(value).toLowerCase());
}

function getConfigValue(rows, key) {
  const row = rows.find((item) => clean(item.json.key).toLowerCase() === key);
  return clean(row?.json.value || '');
}

function splitTerms(value) {
  return clean(value)
    .split(/[,;|\n]/)
    .map((term) => clean(term).toLowerCase())
    .filter(Boolean);
}

function tokenize(value) {
  return clean(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .split(/\s+/)
    .filter((word) => word.length >= 3);
}

function jaccardSimilarity(a, b) {
  const aTokens = new Set(tokenize(a));
  const bTokens = new Set(tokenize(b));

  if (!aTokens.size || !bTokens.size) return 0;

  let intersection = 0;
  for (const token of aTokens) {
    if (bTokens.has(token)) intersection += 1;
  }

  const union = new Set([...aTokens, ...bTokens]).size;
  return intersection / union;
}

function titleSimilarity(title, reference) {
  const titleText = clean(title).toLowerCase();
  const referenceText = clean(reference).toLowerCase();

  if (!titleText || !referenceText) return 0;
  if (titleText.includes(referenceText) || referenceText.includes(titleText)) return 1;

  return jaccardSimilarity(titleText, referenceText);
}

function getBestMatch(title, terms) {
  let bestTerm = '';
  let bestScore = 0;

  for (const term of terms) {
    const score = titleSimilarity(title, term);
    if (score > bestScore) {
      bestScore = score;
      bestTerm = term;
    }
  }

  return { term: bestTerm, score: bestScore };
}

function matchesRole(title, terms) {
  const best = getBestMatch(title, terms);
  return best.score >= 0.25;
}

function getBucket(title, buckets) {
  let bestBucket = '';
  let bestScore = 0;

  for (const bucket of buckets) {
    const best = getBestMatch(title, bucket.terms);

    if (best.score > bestScore) {
      bestScore = best.score;
      bestBucket = bucket.name;
    }
  }

  return bestScore >= 0.25 ? bestBucket : '';
}

function locationMatchesAllowedCountries(location, allowedCountries) {
  const value = clean(location).toLowerCase();

  if (!allowedCountries.length) return true;
  if (!value) return false;

  return allowedCountries.some((country) => {
    const normalized = clean(country).toLowerCase();

    if (['usa', 'us', 'u.s.', 'united states', 'united states of america'].includes(normalized)) {
      return (
        value.includes('united states') ||
        value.includes('usa') ||
        value.includes('u.s.') ||
        value.includes('united states of america') ||
        /\bus-[a-z]{2}\b/i.test(value) ||
        /\b(al|ak|az|ar|ca|co|ct|de|fl|ga|hi|ia|id|il|in|ks|ky|la|ma|md|me|mi|mn|mo|ms|mt|nc|nd|ne|nh|nj|nm|nv|ny|oh|ok|or|pa|ri|sc|sd|tn|tx|ut|va|vt|wa|wi|wv|wy)\b/.test(value)
      );
    }

    return value.includes(normalized);
  });
}

function isWorkdayRow(row) {
  const atsType = clean(row.ats_type).toLowerCase();
  const url = clean(row.career_page_url || row.endpoint).toLowerCase();

  return atsType === 'workday' || url.includes('myworkdayjobs.com') || url.includes('myworkdaysite.com');
}

function deriveWorkdaySource(row) {
  const rawUrl = clean(row.career_page_url || row.endpoint).replace(/\/+$/, '');
  if (!rawUrl) return null;

  const match = rawUrl.match(/^(https?:\/\/)([^/]+)(\/.*)?$/i);
  if (!match) return null;

  const origin = `${match[1]}${match[2]}`;
  const host = match[2];
  const path = match[3] || '';

  const parts = path
    .split('/')
    .filter(Boolean)
    .filter((part) => !/^[a-z]{2}-[A-Z]{2}$/.test(part));

  let tenant = '';
  let site = '';
  let publicBase = '';

  const recruitingIndex = parts.findIndex((part) => part.toLowerCase() === 'recruiting');

  if (host.includes('myworkdaysite.com') && recruitingIndex >= 0) {
    tenant = parts[recruitingIndex + 1] || '';
    site = parts[recruitingIndex + 2] || '';
    publicBase = `${origin}/recruiting/${tenant}/${site}`;
  } else {
    tenant = host.split('.')[0] || '';
    site = parts[0] || clean(row.slug) || '';
    publicBase = `${origin}/${site}`;
  }

  if (!tenant || !site) return null;

  return {
    tenant,
    site,
    apiBase: `${origin}/wday/cxs/${encodeURIComponent(tenant)}/${encodeURIComponent(site)}`,
    publicBase,
  };
}

function parseWorkdayPostedAt(value) {
  const raw = clean(value);
  const lower = raw.toLowerCase();

  if (!raw) return { timestamp: 0, display: '' };

  const directTimestamp = new Date(raw).getTime();
  if (!Number.isNaN(directTimestamp)) return { timestamp: directTimestamp, display: raw };

  if (lower.includes('posted today') || lower === 'today') return { timestamp: Date.now(), display: raw };
  if (lower.includes('posted yesterday') || lower === 'yesterday') return { timestamp: Date.now() - DAY_MS, display: raw };

  return { timestamp: 0, display: raw };
}

function getExternalPath(job) {
  const path = clean(job.externalPath || job.external_path || job.path || '');
  if (!path) return '';

  if (path.startsWith('http')) {
    const match = path.match(/\/job\/.+$/);
    return match ? match[0] : '';
  }

  return path.startsWith('/') ? path : `/${path}`;
}

function getPublicJobUrl(source, externalPath) {
  return externalPath ? `${source.publicBase}${externalPath}` : source.publicBase;
}

function getDetailUrl(source, externalPath) {
  return externalPath ? `${source.apiBase}${externalPath}` : '';
}

function getJobLocation(job, detailInfo) {
