  if (!source) continue;

  const jobsUrl = `${source.apiBase}/jobs`;

  let offset = 0;
  const limit = 5;
  let fetched = 0;
  let total = 0;

  do {
    let response;

    try {
      response = await this.helpers.httpRequest({
        method: 'POST',
        url: jobsUrl,
        headers: {
          Accept: 'application/json',
          'Content-Type': 'application/json',
