      });
    } catch (error) {
      if (DEBUG) {
        out.push({
          json: {
            title: `Workday fetch failed: ${company}`,
            company,
            location: '',
            apply_url: '',
            discovery_url: jobsUrl,
            posted_at: '',
            needs_manual_jd: true,
            full_jd: clean(error.message || error),
            status: 'fetch_error',
            source: 'workday',
            bucket_selected: '',
            score: '',
            rank_reason: '',
          },
        });
      }

      break;
    }

    const jobs = Array.isArray(response?.jobPostings) ? response.jobPostings : [];
    total = Number(response?.total || jobs.length || 0);
    fetched += jobs.length;

    if (DEBUG && offset === 0) {
      out.push({
        json: {
          title: `DEBUG fetched ${jobs.length}/${total}: ${company}`,
          company,
          location: '',
          apply_url: '',
          discovery_url: jobsUrl,
          posted_at: '',
          needs_manual_jd: true,
