          status: 'debug',
          source: 'workday',
          bucket_selected: '',
          score: '',
          rank_reason: '',
        },
      });
    }

    for (const job of jobs) {
      const title = clean(job.title || job.jobTitle || '');
      if (!title) continue;

      if (!matchesRole(title, uniqueTerms)) continue;

      const posted = parseWorkdayPostedAt(job.postedOn || job.posted_on || job.startDate || '');
      if (!posted.timestamp || posted.timestamp < cutoff) continue;

      const externalPath = getExternalPath(job);
      if (!externalPath) continue;

      const detailUrl = getDetailUrl(source, externalPath);
      const publicUrl = getPublicJobUrl(source, externalPath);

      let detail = {};
      try {
        detail = await this.helpers.httpRequest({
          method: 'GET',
          url: detailUrl,
          headers: {
            Accept: 'application/json',
            'User-Agent': 'Mozilla/5.0',
          },
          json: true,
          timeout: 30000,
        });
      } catch (error) {
        detail = {};
      }

      const detailInfo = detail?.jobPostingInfo || detail?.jobPosting || detail || {};
      const location = getJobLocation(job, detailInfo);

      if (!locationMatchesAllowedCountries(location, allowedCountries)) continue;

      const rawJd = getDetailDescription(detail) || job.description || '';
      const fullJd = stripHtml(rawJd).replace(/<[^>]*>/g, ' ').replace(/[ \t]+/g, ' ').trim();

      const bucketSelected = getBucket(title, buckets);

      out.push({
        json: {
          title,
          company,
          location,
          apply_url: publicUrl,
          discovery_url: publicUrl,
          posted_at: posted.display,
          needs_manual_jd: !fullJd,
          full_jd: fullJd,
          status: fullJd ? 'ready' : 'needs_jd',
          source: 'workday',
          bucket_selected: bucketSelected,
          score: '',
          rank_reason: '',
        },
      });
    }

    offset += limit;
  } while (fetched < total && offset < 50);
}

return out;

