        value.includes('u.s.') ||
        value.includes('united states of america') ||
        /\b(al|ak|az|ar|ca|co|ct|de|fl|ga|hi|ia|id|il|in|ks|ky|la|ma|md|me|mi|mn|mo|ms|mt|nc|nd|ne|nh|nj|nm|nv|ny|oh|ok|or|pa|ri|sc|sd|tn|tx|ut|va|vt|wa|wi|wv|wy)\b/.test(value)
      );
    }

    return value.includes(normalized);
  });
}

function getPostedValue(job, detailJob) {
  return clean(
    detailJob?.datePosted ||
    detailJob?.postedDate ||
    detailJob?.createdDate ||
    detailJob?.updatedDate ||
    job.datePosted ||
    job.postedDate ||
    job.createdDate ||
    job.updatedDate ||
    ''
  );
}

function getDetailJob(detail) {
  return detail?.result?.jobOpening || detail?.jobOpening || detail?.result || detail || {};
}

function getDescription(job, detailJob) {
  return (
    detailJob.description ||
    detailJob.jobDescription ||
    detailJob.jobOpeningDescription ||
    detailJob.details ||
    detailJob.content ||
    job.description ||
    job.jobDescription ||
    job.jobOpeningDescription ||
    job.details ||
    ''
  );
}

function getCompaniesFromInput() {
  const inputRows = $input.all().map((item) => item.json);
  const bambooRows = inputRows.filter(isBambooHrRow);

  if (bambooRows.length) return inputRows;

  try {
    return $('Read companies tab').all().map((item) => item.json);
  } catch (error) {
    return inputRows;
  }
}

const configRows = $('Read config tab').all();
const companies = getCompaniesFromInput();

const allowedCountries = splitTerms(getConfigValue(configRows, 'allowed_countries'));

const systemsTitleReferences = splitTerms(getConfigValue(configRows, 'systems_title_references'));
const mechanicalTitleReferences = splitTerms(getConfigValue(configRows, 'mechanical_title_references'));
const controlsTitleReferences = splitTerms(getConfigValue(configRows, 'controls_title_references'));

const systemsKeywords = splitTerms(getConfigValue(configRows, 'systems_keywords'));
const mechanicalKeywords = splitTerms(getConfigValue(configRows, 'mechanical_keywords'));
const controlsKeywords = splitTerms(getConfigValue(configRows, 'controls_keywords'));

const buckets = [
  { name: 'systems', terms: [...systemsTitleReferences, ...systemsKeywords] },
  { name: 'mechanical', terms: [...mechanicalTitleReferences, ...mechanicalKeywords] },
  { name: 'controls', terms: [...controlsTitleReferences, ...controlsKeywords] },
];

const uniqueTerms = [...new Set([
  ...systemsTitleReferences,
  ...mechanicalTitleReferences,
  ...controlsTitleReferences,
  ...systemsKeywords,
  ...mechanicalKeywords,
  ...controlsKeywords,
])];

const bambooCompanies = companies.filter((row) => isEnabled(row.enabled) && isBambooHrRow(row));

const out = [];

if (DEBUG) {
  out.push({
    json: {
      title: 'DEBUG BambooHR input',
      company: '',
      location: '',
      apply_url: '',
      discovery_url: '',
      posted_at: '',
      needs_manual_jd: true,
      full_jd: `input_rows=${companies.length}; enabled_bamboohr_rows=${bambooCompanies.length}; configured_terms=${uniqueTerms.length}; allowed_countries=${allowedCountries.join(', ')}`,
      status: 'debug',
      source: 'bamboohr',
      bucket_selected: '',
      score: '',
      rank_reason: '',
    },
  });
}

for (const companyRow of bambooCompanies) {
  const slug = deriveBambooSlug(companyRow);
  if (!slug) continue;

  const company = clean(companyRow.company) || slug;
  const listUrl = `https://${slug}.bamboohr.com/careers/list`;

  let response;

  try {
    response = await this.helpers.httpRequest({
      method: 'GET',
      url: listUrl,
      headers: {
        Accept: 'application/json',
        'User-Agent': 'Mozilla/5.0',
      },
      json: true,
      timeout: 30000,
    });
  } catch (error) {
    if (DEBUG) {
      out.push({
        json: {
          title: `BambooHR fetch failed: ${company}`,
          company,
          location: '',
          apply_url: '',
          discovery_url: listUrl,
          posted_at: '',
          needs_manual_jd: true,
          full_jd: clean(error.message || error),
          status: 'fetch_error',
          source: 'bamboohr',
          bucket_selected: '',
          score: '',
          rank_reason: '',
        },
      });
    }

    continue;
  }

  const jobs = Array.isArray(response?.result)
    ? response.result
    : Array.isArray(response?.jobs)
      ? response.jobs
      : [];

  if (DEBUG) {
    out.push({
      json: {
        title: `DEBUG fetched ${jobs.length}: ${company}`,
        company,
        location: '',
        apply_url: '',
        discovery_url: listUrl,
        posted_at: '',
        needs_manual_jd: true,
        full_jd: jobs.slice(0, 5).map((job) => getJobTitle(job)).join(' | '),
        status: 'debug',
        source: 'bamboohr',
        bucket_selected: '',
        score: '',
        rank_reason: '',
      },
    });
  }

  for (const job of jobs) {
    const title = getJobTitle(job);
    if (!title) continue;
    if (!matchesRole(title, uniqueTerms)) continue;

    const jobId = getJobId(job);
    if (!jobId) continue;

    const detailUrl = `https://${slug}.bamboohr.com/careers/${encodeURIComponent(jobId)}/detail`;
    const publicUrl = `https://${slug}.bamboohr.com/careers/${encodeURIComponent(jobId)}`;

    let detail = {};
    try {
      detail = await this.helpers.httpRequest({
        method: 'GET',
        url: detailUrl,
        headers: {
          Accept: 'application/json',
          'User-Agent': 'Mozilla/5.0',
        },
        json: true,
        timeout: 30000,
      });
    } catch (error) {
      detail = {};
    }

    const detailJob = getDetailJob(detail);
    const location = getJobLocation(job, detailJob);

    if (!locationMatchesAllowedCountries(location, allowedCountries)) continue;

    const posted = parsePostedAt(getPostedValue(job, detailJob));
    if (!posted.timestamp || posted.timestamp < cutoff) continue;

    const rawJd = getDescription(job, detailJob);
    const fullJd = stripHtml(rawJd);
    const bucketSelected = getBucket(title, buckets);

    out.push({
      json: {
        title,
        company,
        location,
        apply_url: publicUrl,
        discovery_url: publicUrl,
        posted_at: posted.display,
        needs_manual_jd: !fullJd,
        full_jd: fullJd,
        status: fullJd ? 'ready' : 'needs_jd',
        source: 'bamboohr',
        bucket_selected: bucketSelected,
        score: '',
        rank_reason: '',
      },
    });
  }
}

return out;

const DEBUG = false;
const STRICT_24H = true;

const DAY_MS = 24 * 60 * 60 * 1000;
const cutoff = Date.now() - DAY_MS;

function clean(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function decodeHtml(value) {
  return String(value || '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&mdash;/gi, '-')
    .replace(/&ndash;/gi, '-')
    .replace(/&rsquo;/gi, "'")
    .replace(/&lsquo;/gi, "'")
    .replace(/&rdquo;/gi, '"')
    .replace(/&ldquo;/gi, '"')
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
    .replace(/&#x([a-f0-9]+);/gi, (_, code) => String.fromCharCode(parseInt(code, 16)));
}

function stripHtml(html) {
  return decodeHtml(String(html || ''))
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|ul|ol|h1|h2|h3|h4|h5|h6|tr|dd|dt)>/gi, '\n')
    .replace(/<li[^>]*>/gi, '- ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\r/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n[ \t]+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function isEnabled(value) {
  return value === true || value === 1 || ['true', '1', 'yes', 'y'].includes(clean(value).toLowerCase());
}

function getConfigValue(rows, key) {
  const row = rows.find((item) => clean(item.json.key).toLowerCase() === key);
  return clean(row?.json.value || '');
}

function splitTerms(value) {
  return clean(value)
    .split(/[,;|\n]/)
    .map((term) => clean(term).toLowerCase())
    .filter(Boolean);
}

function isIcimsRow(row) {
  const atsType = clean(row.ats_type).toLowerCase();
  const url = clean(row.career_page_url || row.endpoint).toLowerCase();
  return atsType === 'icims' || url.includes('.icims.com');
}

function normalizeUrl(url) {
  let raw = decodeHtml(clean(url));
  if (!raw) return '';

  raw = raw.split('#')[0];

  const parts = raw.split('?');
  const base = parts[0];
  const query = parts[1] || '';
  if (!query) return base;

  const removeParams = [
    'utm_source',
    'utm_medium',
    'utm_campaign',
    'utm_term',
    'utm_content',
    'mode',
    'iis',
    'iisn',
    'mobile',
    'width',
    'height',
    'bga',
    'needsRedirect',
  ];

  const keptParams = query
    .split('&')
    .filter(Boolean)
    .filter((pair) => !removeParams.includes(pair.split('=')[0]));

  return keptParams.length ? `${base}?${keptParams.join('&')}` : base;
}

function getOrigin(url) {
  const match = clean(url).match(/^(https?:\/\/[^/]+)/i);
  return match ? match[1] : '';
}

function absolutizeUrl(url, baseUrl) {
  const raw = decodeHtml(clean(url));
  if (!raw) return '';

  if (/^https?:\/\//i.test(raw)) return normalizeUrl(raw);

  const origin = getOrigin(baseUrl);
  if (!origin) return raw;

  if (raw.startsWith('/')) return normalizeUrl(origin + raw);

  const basePath = clean(baseUrl).replace(/[#?].*$/, '').replace(/\/[^/]*$/, '/');
  return normalizeUrl(basePath + raw);
}

function getIcimsSearchBase(row) {
  const rawUrl = clean(row.career_page_url || row.endpoint);
  if (!rawUrl) return '';

  const noHash = rawUrl.split('#')[0];

  if (/\/jobs\/search/i.test(noHash)) return noHash.split('?')[0];

  const match = noHash.match(/^(https?:\/\/[^/]+)\/?/i);
  return match ? `${match[1]}/jobs/search` : '';
}

function buildSearchUrl(searchBase, page) {
  const base = clean(searchBase).split('?')[0];
  return `${base}?pr=${encodeURIComponent(String(page))}&searchRelation=keyword_all&in_iframe=1`;
}

function matchesRole(title, terms) {
  const normalizedTitle = clean(title).toLowerCase();

  if (terms.some((term) => normalizedTitle.includes(term))) return true;

  return (
    normalizedTitle.includes('system') ||
    normalizedTitle.includes('systems') ||
    normalizedTitle.includes('mechanical') ||
    normalizedTitle.includes('controls') ||
    normalizedTitle.includes('control') ||
    normalizedTitle.includes('automation') ||
    normalizedTitle.includes('mechatronics') ||
    normalizedTitle.includes('manufacturing engineer') ||
    normalizedTitle.includes('process engineer') ||
    normalizedTitle.includes('test engineer') ||
    normalizedTitle.includes('electrical engineer') ||
    normalizedTitle.includes('field service engineer')
  );
}

function tokenize(value) {
  return clean(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .split(/\s+/)
    .filter((word) => word.length >= 3);
}

function jaccardSimilarity(a, b) {
  const aTokens = new Set(tokenize(a));
  const bTokens = new Set(tokenize(b));

  if (!aTokens.size || !bTokens.size) return 0;

  let intersection = 0;
  for (const token of aTokens) {
    if (bTokens.has(token)) intersection += 1;
  }

  const union = new Set([...aTokens, ...bTokens]).size;
  return intersection / union;
}

function titleSimilarity(title, reference) {
  const titleText = clean(title).toLowerCase();
  const referenceText = clean(reference).toLowerCase();

  if (!titleText || !referenceText) return 0;

  if (titleText.includes(referenceText) || referenceText.includes(titleText)) {
    return 1;
  }

  return jaccardSimilarity(titleText, referenceText);
}

function getBucket(title, buckets) {
  let bestBucket = '';
  let bestScore = 0;

  for (const bucket of buckets) {
    for (const referenceTitle of bucket.terms) {
      const score = titleSimilarity(title, referenceTitle);

      if (score > bestScore) {
        bestScore = score;
        bestBucket = bucket.name;
      }
    }
  }

  // Tune this if needed. 0.25 catches things like:
  // "Mechanical Commissioning Engineer" vs "Mechanical Engineer"
  // "Systems Integration Engineer" vs "Systems Engineer"
  return bestScore >= 0.25 ? bestBucket : '';
}

function locationMatchesAllowedCountries(location, allowedCountries) {
  const value = clean(location).toLowerCase();

  if (!allowedCountries.length) return true;
  if (!value) return false;

  return allowedCountries.some((country) => {
    const normalized = clean(country).toLowerCase();

    if (['usa', 'us', 'u.s.', 'united states', 'united states of america'].includes(normalized)) {
      return (
        value.includes('united states') ||
        value.includes('usa') ||
        value.includes('u.s.') ||
        value.includes('united states of america') ||
        /\bus-[a-z]{2}\b/i.test(value) ||
        /\b(al|ak|az|ar|ca|co|ct|de|fl|ga|hi|ia|id|il|in|ks|ky|la|ma|md|me|mi|mn|mo|ms|mt|nc|nd|ne|nh|nj|nm|nv|ny|oh|ok|or|pa|ri|sc|sd|tn|tx|ut|va|vt|wa|wi|wv|wy)\b/.test(value)
      );
    }

    return value.includes(normalized);
  });
}

function parsePostedAt(value) {
  const raw = clean(value);
  if (!raw) return { timestamp: 0, display: '' };

  let timestamp = new Date(raw).getTime();

  if (Number.isNaN(timestamp)) {
    const relativeMatch = raw.toLowerCase().match(/(\d+)\s+(hour|hours|day|days)\s+ago/);
    if (relativeMatch) {
      const amount = Number(relativeMatch[1]);
      const unit = relativeMatch[2];
      timestamp = Date.now() - amount * (unit.startsWith('hour') ? 60 * 60 * 1000 : DAY_MS);
    }
  }

  if (Number.isNaN(timestamp)) return { timestamp: 0, display: raw };

  return { timestamp, display: raw };
}

function extractJobLinksFromSearch(html, baseUrl) {
  const links = new Set();
  const source = String(html || '');
  const hrefRegex = /href=["']([^"']*\/jobs\/\d+\/[^"']*)["']/gi;
  let match;

  while ((match = hrefRegex.exec(source)) !== null) {
    let url = absolutizeUrl(match[1], baseUrl);

    if (url && /\/jobs\/\d+\//i.test(url)) {
      // iCIMS needs in_iframe=1 to return the actual job detail content.
      if (!/[?&]in_iframe=1\b/i.test(url)) {
        url += url.includes('?') ? '&in_iframe=1' : '?in_iframe=1';
      }

      links.add(url);
    }
  }

  return [...links];
}

function extractJsonLd(html) {
  const source = String(html || '');
  const scripts = source.match(/<script[^>]*type=["']application\/ld\+json["'][^>]*>[\s\S]*?<\/script>/gi) || [];

  for (const script of scripts) {
    const jsonText = script
      .replace(/^<script[^>]*>/i, '')
      .replace(/<\/script>$/i, '')
      .trim();

    try {
      const data = JSON.parse(jsonText);
      if (data && (data.title || data.datePosted || data.jobLocation)) return data;
    } catch (error) {}
  }

  return {};
}

function extractBetween(html, patterns) {
  const source = String(html || '');

  for (const pattern of patterns) {
    const match = source.match(pattern);
    if (match?.[1]) return stripHtml(match[1]);
  }

  return '';
}

function extractHeaderField(html, label) {
  const source = String(html || '');
  const escapedLabel = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  const patterns = [
    new RegExp(`<dt[^>]*>\\s*${escapedLabel}\\s*<\\/dt>\\s*<dd[^>]*>([\\s\\S]*?)<\\/dd>`, 'i'),
    new RegExp(`<span[^>]*class=["'][^"']*field-label[^"']*["'][^>]*>\\s*${escapedLabel}\\s*<\\/span>\\s*<span[^>]*>([\\s\\S]*?)<\\/span>`, 'i'),
  ];

  return extractBetween(source, patterns);
}

function extractTitle(html) {
  const jsonLd = extractJsonLd(html);

  return clean(
    jsonLd.title ||
    extractBetween(html, [
      /<h1[^>]*class=["'][^"']*(?:job-title|iCIMS_Header)[^"']*["'][^>]*>([\s\S]*?)<\/h1>/i,
      /<h1[^>]*>([\s\S]*?)<\/h1>/i,
      /property=["']og:title["'][^>]*content=["']([^"']+)["']/i,
      /<title[^>]*>([\s\S]*?)<\/title>/i,
    ]).replace(/\s+in\s+.*$/i, '').replace(/\s+-\s+.*$/i, '')
  );
}

function extractLocation(html) {
  const jsonLd = extractJsonLd(html);
  const locations = Array.isArray(jsonLd.jobLocation) ? jsonLd.jobLocation : [jsonLd.jobLocation].filter(Boolean);

  const jsonLocation = locations
    .map((loc) => {
      const address = loc?.address || loc || {};
      return clean([
        address.addressLocality,
        address.addressRegion,
        address.addressCountry,
      ].filter(Boolean).join(', '));
    })
    .filter(Boolean)
    .join(' | ');

  return clean(
    jsonLocation ||
    extractHeaderField(html, 'Location') ||
    extractHeaderField(html, 'Job Location') ||
    extractHeaderField(html, 'Job Location(s)') ||
    extractBetween(html, [
      /<span[^>]*class=["'][^"']*location[^"']*["'][^>]*>([\s\S]*?)<\/span>/i,
    ])
  );
}

function extractPostedAt(html) {
  const jsonLd = extractJsonLd(html);

  return clean(
    jsonLd.datePosted ||
    extractHeaderField(html, 'Posted Date') ||
    extractHeaderField(html, 'Date Posted') ||
    extractHeaderField(html, 'Posted') ||
    extractBetween(html, [
      /<span[^>]*title=["']([^"']+)["'][^>]*>\s*\d+\s+(?:hour|hours|day|days)\s+ago/i,
      /<span[^>]*class=["'][^"']*posted[^"']*["'][^>]*>([\s\S]*?)<\/span>/i,
    ])
  );
}

function extractFullJd(html) {
  const jsonLd = extractJsonLd(html);

  if (jsonLd.description) {
    return stripHtml(jsonLd.description);
  }

  return extractBetween(html, [
    /<h2[^>]*class=["'][^"']*iCIMS_InfoField_Job[^"']*["'][^>]*>[\s\S]*?<\/h2>\s*<div[^>]*class=["'][^"']*iCIMS_InfoMsg_Job[^"']*["'][^>]*>([\s\S]*?)<div[^>]*id=["']icims-social-share/i,
    /<div[^>]*class=["'][^"']*iCIMS_InfoMsg_Job[^"']*["'][^>]*>([\s\S]*?)<\/div>\s*<h2/i,
    /<div[^>]*class=["'][^"']*iCIMS_JobContent[^"']*["'][^>]*>([\s\S]*?)<div[^>]*id=["']icims-social-share/i,
    /<div[^>]*class=["'][^"']*iCIMS_JobContent[^"']*["'][^>]*>([\s\S]*?)<\/main>/i,
    /<section[^>]*class=["'][^"']*job-description[^"']*["'][^>]*>([\s\S]*?)<\/section>/i,
    /<div[^>]*id=["']job-description["'][^>]*>([\s\S]*?)<\/div>/i,
    /<div[^>]*class=["'][^"']*description[^"']*["'][^>]*>([\s\S]*?)<\/div>/i,
  ]);
}

function getCompaniesFromInput() {
  const inputRows = $input.all().map((item) => item.json);
  const icimsRows = inputRows.filter(isIcimsRow);

  if (icimsRows.length) return inputRows;

