  } catch (error) {
    return inputRows;
  }
}

function debugRow(title, company, discoveryUrl, message) {
  return {
    json: {
      title,
      company: company || '',
      location: '',
      apply_url: '',
      discovery_url: discoveryUrl || '',
      posted_at: '',
      needs_manual_jd: true,
      full_jd: message || '',
      status: 'debug',
      source: 'icims',
      bucket_selected: '',
      score: '',
      rank_reason: '',
    },
  };
}

const configRows = $('Read config tab').all();
const companies = getCompaniesFromInput();

const allowedCountries = splitTerms(getConfigValue(configRows, 'allowed_countries'));

const systemsTerms = splitTerms(getConfigValue(configRows, 'systems_title_references'));
const mechanicalTerms = splitTerms(getConfigValue(configRows, 'mechanical_title_references'));
const controlsTerms = splitTerms(getConfigValue(configRows, 'controls_title_references'));

const buckets = [
  { name: 'systems', terms: systemsTerms },
  { name: 'mechanical', terms: mechanicalTerms },
  { name: 'controls', terms: controlsTerms },
];

const configuredTerms = [...new Set([...systemsTerms, ...mechanicalTerms, ...controlsTerms])];

const fallbackTerms = [
  'systems engineer',
  'system engineer',
  'mechanical engineer',
  'controls engineer',
  'control systems engineer',
  'automation engineer',
  'mechatronics engineer',
  'manufacturing engineer',
  'electrical engineer',
  'test engineer',
  'field service engineer',
];

const titleTerms = configuredTerms.length ? configuredTerms : fallbackTerms;
const icimsCompanies = companies.filter((row) => isEnabled(row.enabled) && isIcimsRow(row));

const out = [];

if (DEBUG) {
  out.push(debugRow(
    'DEBUG iCIMS input',
    '',
    '',
    `input_rows=${companies.length}; enabled_icims_rows=${icimsCompanies.length}; allowed_countries=${allowedCountries.join(', ')}; strict_24h=${STRICT_24H}`
  ));
}

for (const companyRow of icimsCompanies) {
  const company = clean(companyRow.company);
  const searchBase = getIcimsSearchBase(companyRow);

  if (!searchBase) continue;

  const jobLinks = new Set();

  for (let page = 0; page < 3; page++) {
    const searchUrl = buildSearchUrl(searchBase, page);

    let html = '';
    try {
      html = await this.helpers.httpRequest({
        method: 'GET',
        url: searchUrl,
        headers: {
          Accept: 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
          'User-Agent': 'Mozilla/5.0',
        },
        timeout: 30000,
      });
    } catch (error) {
      if (DEBUG) out.push(debugRow(`iCIMS search failed: ${company}`, company, searchUrl, clean(error.message || error)));
      break;
    }

    const links = extractJobLinksFromSearch(html, searchUrl);
    links.forEach((link) => jobLinks.add(link));

    if (!links.length) break;
  }

  if (DEBUG) {
    out.push(debugRow(`DEBUG iCIMS links: ${company}`, company, searchBase, `links_found=${jobLinks.size}`));
  }

  const skip = {
    noTitle: 0,
    role: 0,
    location: 0,
    date: 0,
    fetch: 0,
  };

  let emitted = 0;

  for (const jobUrl of jobLinks) {
    let detailHtml = '';

    try {
      detailHtml = await this.helpers.httpRequest({
        method: 'GET',
        url: jobUrl,
        headers: {
          Accept: 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
          'User-Agent': 'Mozilla/5.0',
        },
        timeout: 30000,
      });
    } catch (error) {
      skip.fetch += 1;
      continue;
    }

    const title = extractTitle(detailHtml);
    if (!title) {
      skip.noTitle += 1;
      continue;
    }

    if (!matchesRole(title, titleTerms)) {
      skip.role += 1;
      continue;
    }

    const location = extractLocation(detailHtml);
    if (!locationMatchesAllowedCountries(location, allowedCountries)) {
      skip.location += 1;
      continue;
    }

    const posted = parsePostedAt(extractPostedAt(detailHtml));
    if (STRICT_24H && (!posted.timestamp || posted.timestamp < cutoff)) {
      skip.date += 1;
      continue;
    }

    const fullJd = extractFullJd(detailHtml);
    const bucketSelected = getBucket(title, buckets);

    emitted += 1;

    out.push({
      json: {
        title,
        company,
        location,
        apply_url: jobUrl,
        discovery_url: jobUrl,
        posted_at: posted.display,
        needs_manual_jd: !fullJd,
        full_jd: fullJd,
        status: fullJd ? 'ready' : 'needs_jd',
        source: 'icims',
        bucket_selected: bucketSelected,
        score: '',
        rank_reason: '',
      },
    });
  }

  if (DEBUG) {
    out.push(debugRow(
      `DEBUG iCIMS parsed: ${company}`,
      company,
      searchBase,
      `emitted=${emitted}; skipped_fetch=${skip.fetch}; skipped_no_title=${skip.noTitle}; skipped_role=${skip.role}; skipped_location=${skip.location}; skipped_date=${skip.date}`
    ));
  }
}

return out;

function clean(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function normalizeUrl(value) {
  return clean(value)
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/[?#].*$/, '')
    .replace(/\/+$/, '');
}

function normalizeText(value) {
  return clean(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function makeCompanyTitleKey(row) {
  const company = normalizeText(row.company);
  const title = normalizeText(row.title);
  return company && title ? `${company}|${title}` : '';
}

const newJobs = $input.all();

let existingRows = [];
try {
  existingRows = $('Read existing jobs tab').all();
} catch (error) {
  existingRows = [];
}

const seenUrls = new Set();
const seenCompanyTitle = new Set();

for (const item of existingRows) {
  const row = item.json || {};

  const existingUrl = normalizeUrl(row.discovery_url || row.apply_url);
  if (existingUrl) seenUrls.add(existingUrl);

  const existingCompanyTitle = makeCompanyTitleKey(row);
  if (existingCompanyTitle) seenCompanyTitle.add(existingCompanyTitle);
}

const out = [];

for (const item of newJobs) {
  const job = item.json || {};

  const jobUrl = normalizeUrl(job.discovery_url || job.apply_url);
  const jobCompanyTitle = makeCompanyTitleKey(job);

  if (jobUrl && seenUrls.has(jobUrl)) continue;
  if (jobCompanyTitle && seenCompanyTitle.has(jobCompanyTitle)) continue;

  if (jobUrl) seenUrls.add(jobUrl);
  if (jobCompanyTitle) seenCompanyTitle.add(jobCompanyTitle);

  out.push(item);
}

return out;
